<script setup lang="ts">
import {computed,onDeactivated,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {NAlert,NButton,NDrawer,NDrawerContent,NInput,NModal,NPopconfirm,NSelect,NSlider,NSwitch,NTabs,NTabPane} from 'naive-ui';
import {Download,Monitor,Pin,Plus,Settings2,Sparkles,Trash2} from 'lucide-vue-next';
import type {ControlStore} from '../control-types.ts';
import {EXPRESSION_NAMES,EXPRESSIONS} from '../../companion/expressions.ts';
import ResourceLibraryPage from '../components/ResourceLibraryPage.vue';
import ResourceShareActions from '../components/ResourceShareActions.vue';
import PetActor from '../../pets/PetActor.vue';
import {createPetClient} from '../../pets/client.ts';
import {definitionOf,type PetTheme,type PetInstance} from '../../pets/model.ts';
import {petImage} from '../../pets/render.ts';
import {invoke} from '../../bridge.ts';
const props=defineProps<{store:ControlStore;settingsRequest?:{id:string}|null}>();
const emit=defineEmits<{settingsOpened:[]}>();
const client=createPetClient(),{catalog,ready,busy,error}=client;
const category=ref<'builtin'|'custom'|'desktop'>('builtin'),hover=ref(''),editing=ref<string|null>(null);
const adding=ref<{themeId:string;petId:string;name:string}|null>(null),name=ref(''),draftSize=ref(210);
const themes=computed(()=>catalog.value.themes.filter(t=>t.source===category.value));
const instances=computed(()=>catalog.value.layout.instances);
const current=computed(()=>instances.value.find(p=>p.id===editing.value));
const currentDefinition=computed(()=>current.value?definitionOf(catalog.value.themes,current.value):undefined);
const currentTheme=computed(()=>catalog.value.themes.find(t=>t.id===current.value?.themeId));
interface GreetingSettings {enabled:boolean;frequency:string;calendarRegion?:'CN'|null}
const greetingSettings=ref<GreetingSettings>({enabled:false,frequency:'natural',calendarRegion:null}),greetingReady=ref(false),greetingBusy=ref(false);
const calendarRegions=[{label:'未指定 · 不推断法定工作日',value:'none'},{label:'中国大陆 · 2026 年官方调休',value:'CN'}];
const greetingModes=[{label:'安静陪伴 · 最多每天 1 次',value:'quiet'},{label:'自然陪伴 · 最多每天 2 次',value:'natural'},{label:'活泼伙伴 · 最多每天 4 次',value:'lively'}];
async function loadGreeting(){if(!props.store.desktop)return;try{const result=await invoke<GreetingSettings>('get_proactivity_settings');if(result){greetingSettings.value=result;greetingReady.value=true;}}catch(e){props.store.notify(e,'error');}}
async function changeGreeting(patch:Partial<GreetingSettings>){if(!greetingReady.value||greetingBusy.value)return;greetingBusy.value=true;try{greetingSettings.value=await invoke<GreetingSettings>('configure_proactivity',{settings:{...greetingSettings.value,...patch}});props.store.notify('主动陪伴设置已保存');}catch(e){props.store.notify(e,'error');}finally{greetingBusy.value=false;}}
const petChoices=computed(()=>catalog.value.themes.flatMap(t=>t.pets.map(p=>({label:`${t.name} · ${p.name}`,value:`${t.id}/${p.id}`}))));
function openManage(id:string){category.value='desktop';editing.value=id;}
function changePet(value:string){const [themeId,petId]=value.split('/');update({themeId,petId});}
const expressions=EXPRESSION_NAMES.map(value=>({label:EXPRESSIONS[value].label,value}));
const layers=[{label:'悬浮陪伴 · 始终置顶',value:'topmost'},{label:'贴在桌面 · 不遮挡窗口',value:'desktop'}];
async function act(action:()=>Promise<unknown>,success?:string){try{await action();if(success)props.store.notify(success);}catch(e){props.store.notify(e,'error');}}
const placements=[{value:'topmost' as const,label:'始终置顶',hint:'显示在其他窗口上方，随时陪着你',icon:Pin},{value:'desktop' as const,label:'贴在桌面',hint:'放在桌面上，不遮挡其他窗口',icon:Monitor}];
function requestAdd(themeId:string,petId:string,name:string){if(ready.value&&!busy.value)adding.value={themeId,petId,name};}
async function add(layer:PetInstance['layer']){const target=adding.value;if(!target)return;adding.value=null;await act(async()=>{await client.add(target.themeId,target.petId,layer);if(!props.store.settings.companionEnabled)await props.store.setCompanion(true);},'已添加到桌面，可拖动位置，右键管理');}
function create(base?:PetTheme){void props.store.startCreation('pet').then(()=>{if(base)props.store.creationDraft=`请以宠物主题「${base.name}」（${base.id}）为参考，创作我的自定义宠物主题。先读取 pet_read_format 和现有主题，按我的要求调整：`;});}
let sizeTimer:ReturnType<typeof setTimeout>|undefined,pendingSize:{id:string;size:number}|undefined;
function flushSize(){clearTimeout(sizeTimer);const pending=pendingSize;pendingSize=undefined;if(pending)void act(()=>client.update(pending.id,{size:pending.size}));}
function resizePet(size:number){draftSize.value=size;if(!current.value)return;pendingSize={id:current.value.id,size};clearTimeout(sizeTimer);sizeTimer=setTimeout(flushSize,300);}
function update(patch:Partial<PetInstance>){if(current.value)void act(()=>client.update(current.value!.id,patch));}
watch([()=>props.settingsRequest,ready],([request,loaded])=>{if(request&&loaded){openManage(request.id);emit('settingsOpened');}},{immediate:true});
watch(()=>current.value?.id,()=>{flushSize();name.value=current.value?.name||'';});
watch(()=>current.value?.size,value=>{draftSize.value=value??210;});
function manage(e:Event){const id=(e as CustomEvent<{id:string}>).detail?.id;void client.load().then(()=>{if(id)openManage(id);});}
onMounted(()=>{void client.load();void loadGreeting();window.addEventListener('pets-manage',manage);});
onDeactivated(()=>{hover.value='';});
onBeforeUnmount(()=>{flushSize();client.dispose();window.removeEventListener('pets-manage',manage);});
</script>
<template>
<ResourceLibraryPage title="桌面宠物" :active-tab="category" class="pet-library" data-testid="companion-page">
 <template #actions><ResourceShareActions :store="store" kind="pet" import-label="导入宠物" :disabled="!ready||busy" @imported="async()=>{await client.load();category='custom';}"/><NButton round type="primary" data-testid="pet-create" @click="create()"><template #icon><Sparkles :size="16"/></template>创作宠物</NButton></template>
 <template #tabs><NTabs v-model:value="category" type="line" size="large" class="pet-library-tabs"><NTabPane name="builtin"><template #tab>官方主题</template></NTabPane><NTabPane name="custom"><template #tab>自定义主题</template></NTabPane><NTabPane name="desktop"><template #tab>桌面伙伴<span class="pet-tab-count">{{ instances.length }}</span></template></NTabPane></NTabs></template>
 <NAlert v-if="error" type="error" :show-icon="false">{{ error }}<NButton text @click="client.load()">重新载入</NButton></NAlert>
 <div v-if="ready&&category==='custom'&&!themes.length" class="pet-empty surface" data-testid="pet-custom-empty"><Sparkles :size="28"/><h2>你想象中的小伙伴，在这里诞生。</h2><p>让 AI 创作你喜欢的小伙伴，也可以导入别人分享的 ZIP 宠物资源包。</p><NButton type="primary" round @click="create()">开始创作</NButton></div>
 <section v-for="theme in themes" :key="theme.id" class="pet-theme-detail" :data-testid="`pet-theme-${theme.id}`">
  <header class="pet-section-heading"><div><h2>{{ theme.name }}<span>{{ theme.pets.length }} 款宠物</span></h2><p>{{ theme.description }}</p><p v-if="theme.source==='custom'" class="pet-theme-export-note" data-testid="pet-theme-export-note">导出或分享整套主题（含 {{ theme.pets.length }} 款形象），不包含桌面位置、昵称或心情。</p></div><div class="theme-actions"><ResourceShareActions v-if="theme.source==='custom'" :store="store" kind="pet" :id="theme.id" :disabled="busy"/><button @click="create(theme)"><Sparkles :size="14"/>基于此主题创作</button><button v-if="theme.source==='builtin'" :disabled="busy" title="导出参考 JSON" data-testid="pet-export-reference" @click="act(()=>client.exportTheme(theme.id))"><Download :size="16"/>导出参考 JSON</button><NPopconfirm v-if="theme.source==='custom'" @positive-click="act(()=>client.deleteTheme(theme.id))"><template #trigger><button :disabled="busy" title="删除主题"><Trash2 :size="16"/></button></template>删除这个自定义主题？已添加的宠物需先移除。</NPopconfirm></div></header>
  <div class="pet-cards"><article v-for="p in theme.pets" :key="p.id" class="pet-card surface" :data-testid="`pet-card-${p.id}`" @pointerenter="hover=`${theme.id}/${p.id}`" @pointerleave="hover=''">
   <div class="pet-card-stage" :style="{'--theme-color':theme.color}"><PetActor v-if="hover===`${theme.id}/${p.id}`" :definition="p" :size="176" :paused="store.settings.paused"/><img v-else :src="petImage(p)" :alt="p.name" width="176" height="176"/><span class="pet-stage-hint">戳一戳，会回应你</span></div><div class="pet-card-copy"><h3>{{ p.name }}</h3><p>{{ p.description }}</p></div><NButton round block :disabled="!ready||busy" :data-testid="`pet-add-${p.id}`" @click="requestAdd(theme.id,p.id,p.name)" aria-haspopup="dialog" :aria-expanded="adding?.themeId===theme.id&&adding?.petId===p.id"><template #icon><Plus :size="15"/></template>添加到桌面</NButton>
  </article></div>
 </section>
 <section v-if="category==='desktop'" class="desktop-pets surface" data-testid="desktop-pets"><header class="pet-section-heading"><div><h2>桌面上的伙伴<span>{{ instances.length }} 只</span></h2><p>每一只都有独立的心情和位置。同一款，也可以多养几只。</p></div><label class="all-pets-switch"><span>全部显示</span><NSwitch :value="store.settings.companionEnabled" @update:value="value=>act(()=>store.setCompanion(value))"/></label></header>
  <div v-if="store.desktop" class="pet-proactivity-panel" data-testid="pet-proactivity-settings"><div class="pet-proactivity-copy"><strong>主动陪伴</strong><p>偶尔停留在宠物身上，它会轻声搭话。不自动朗读、不读取屏幕，也不会主动联系 AI。默认关闭，尊重免打扰和频率限制。</p></div><div class="pet-proactivity-controls"><NSwitch :value="greetingSettings.enabled" :disabled="!greetingReady||greetingBusy" data-testid="pet-proactivity-switch" @update:value="enabled=>changeGreeting({enabled})"/><NSelect :value="greetingSettings.calendarRegion??'none'" :options="calendarRegions" :disabled="!greetingReady||greetingBusy" size="small" style="width:235px" data-testid="pet-proactivity-calendar" @update:value="region=>changeGreeting({calendarRegion:region==='CN'?'CN':null})"/><NSelect :value="greetingSettings.frequency" :options="greetingModes" :disabled="!greetingReady||greetingBusy" size="small" style="width:220px" data-testid="pet-proactivity-frequency" @update:value="frequency=>changeGreeting({frequency})"/></div></div>
  <div v-if="!instances.length" class="desktop-pets-empty">还没有小伙伴，挑一只喜欢的添加到桌面吧。<NButton text type="primary" @click="category='builtin'">去挑选伙伴</NButton></div>
  <div v-else class="desktop-pet-list"><div v-for="p in instances" :key="p.id" class="desktop-pet-row" :data-testid="`pet-instance-${p.id}`"><img v-if="definitionOf(catalog.themes,p)" :src="petImage(definitionOf(catalog.themes,p)!)" alt="" width="58" height="58"/><div class="desktop-pet-name"><strong>{{ p.name }}</strong><small>{{ catalog.themes.find(t=>t.id===p.themeId)?.name||'作品暂不可用' }} · {{ p.size }}px · {{ p.layer==='desktop'?'贴在桌面':'悬浮陪伴' }}</small></div><span class="pet-mood">{{ EXPRESSIONS[p.expression].label }}</span><NSwitch :value="p.enabled" size="small" :disabled="busy" :aria-label="`显示${p.name}`" @update:value="enabled=>act(()=>client.update(p.id,{enabled}))"/><button class="pet-manage" :aria-label="`管理${p.name}`" :data-testid="`pet-manage-${p.id}`" @click="editing=p.id"><Settings2 :size="16"/></button></div></div>
 </section>
 <NModal :show="!!adding" @update:show="show=>{if(!show)adding=null}">
  <section v-if="adding" class="pet-placement-dialog surface" role="dialog" aria-modal="true" aria-labelledby="pet-placement-title" data-testid="pet-placement-dialog">
   <header><h2 id="pet-placement-title">把{{ adding.name }}放在哪里？</h2><p>之后也可以在伙伴设置中修改。</p></header>
   <button v-for="option in placements" :key="option.value" type="button" class="pet-placement-option" :data-testid="`pet-placement-${option.value}`" :disabled="busy||!ready" @click="add(option.value)"><component :is="option.icon" :size="21"/><span><b>{{ option.label }}</b><small>{{ option.hint }}</small></span></button>
   <NButton quaternary block data-testid="pet-placement-cancel" @click="adding=null">取消</NButton>
  </section>
 </NModal>
 <NDrawer :show="!!current" :width="390" placement="right" @update:show="value=>{if(!value)editing=null}"><NDrawerContent v-if="current" :title="current.name" closable><div class="pet-editor"><div class="pet-editor-stage"><PetActor v-if="currentDefinition" :definition="currentDefinition" :size="210" :expression="current.expression" :links="current.links" :paused="store.settings.paused"/></div><label>宠物形象<NSelect :value="`${current.themeId}/${current.petId}`" :options="petChoices" filterable data-testid="pet-change-plant" @update:value="changePet"/></label><label>名字<NInput v-model:value="name" :maxlength="40" @blur="name.trim()&&update({name:name.trim()})"/></label><label>角色大小 <span>{{ draftSize }} px</span><NSlider :value="draftSize" :min="80" :max="420" :step="10" @update:value="resizePet" @dragend="flushSize"/></label><label>显示层级<NSelect :value="current.layer" :options="layers" @update:value="layer=>update({layer})"/></label><label>心情<NSelect :value="current.expression" :options="expressions" @update:value="expression=>update({expression})"/></label><div class="pet-editor-toggle"><div><b>回应桌面状态</b><p>特效、问候和离开后的重逢。</p></div><NSwitch :value="current.links" @update:value="links=>update({links})"/></div><NButton block @click="update({x:.5,y:.5})">移到屏幕中间</NButton><NButton block @click="create(catalog.themes.find(t=>t.id===current!.themeId))"><template #icon><Sparkles :size="15"/></template>让 AI 换一个形象</NButton><div v-if="currentTheme?.source==='custom'" class="pet-share-panel" data-testid="pet-instance-share"><b>分享这款宠物形象</b><p>打包当前所属的整个主题，不包含这只宠物的个人设置。</p><ResourceShareActions :store="store" kind="pet" :id="current!.themeId" :disabled="busy"/></div><NPopconfirm @positive-click="act(async()=>{await client.remove(current!.id);editing=null;})"><template #trigger><NButton block quaternary type="error" :disabled="busy">从桌面移除</NButton></template>移除这只宠物？主题作品仍会保留。</NPopconfirm></div></NDrawerContent></NDrawer>
</ResourceLibraryPage>
</template>
<style scoped>
.pet-proactivity-panel{margin-top:18px;padding:15px 16px;border-radius:13px;background:var(--ui-surface-alt);display:flex;align-items:center;justify-content:space-between;gap:18px}.pet-proactivity-copy{flex:1}.pet-proactivity-copy strong{font-size:13px;font-weight:600}.pet-proactivity-copy p{font-size:11px;line-height:1.65;color:var(--ui-text-secondary);margin:7px 0 0}.pet-proactivity-controls{display:flex;align-items:center;gap:14px;flex:none;flex-wrap:wrap}@media(max-width:950px){.pet-proactivity-panel{flex-wrap:wrap}.pet-proactivity-controls{width:100%;justify-content:space-between}}
.pet-placement-dialog{width:372px;max-width:calc(100vw - 32px);padding:24px;border-radius:18px;display:grid;gap:12px;color:var(--ui-text-primary)}.pet-placement-dialog h2{font-size:17px;font-weight:600;margin:0}.pet-placement-dialog header p{font-size:12px;color:var(--ui-text-secondary);margin:7px 0 6px}.pet-placement-option{display:flex;align-items:center;gap:14px;width:100%;padding:16px;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-surface);color:var(--ui-text-primary);text-align:left;cursor:pointer;font:inherit}.pet-placement-option:hover{border-color:var(--ui-primary);background:var(--ui-primary-soft)}.pet-placement-option>svg{flex:none;color:var(--ui-primary)}.pet-placement-option span{display:grid;gap:5px}.pet-placement-option b{font-size:14px;font-weight:600}.pet-placement-option small{font-size:12px;color:var(--ui-text-secondary)}
.pet-section-heading p{font-size:12px;line-height:1.7;margin:0;color:var(--ui-text-secondary)}.pet-theme-detail{display:flex;flex-direction:column;gap:18px}.pet-theme-detail+.pet-theme-detail{padding-top:28px;border-top:1px solid var(--ui-border)}.pet-section-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.pet-section-heading h2{display:flex;align-items:center;gap:10px;font-size:18px;margin:0 0 6px;font-weight:650}.pet-section-heading h2>span{font-size:11px;font-weight:400;color:var(--ui-text-tertiary);letter-spacing:0}.theme-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}.pet-theme-export-note{margin-top:5px!important;font-size:11px!important}.pet-share-panel{display:grid;gap:9px;padding:16px;border-radius:12px;background:var(--ui-surface-alt)}.pet-share-panel b{font-size:12px;font-weight:600}.pet-share-panel p{margin:0;font-size:11px;line-height:1.6;color:var(--ui-text-secondary)}.theme-actions button,.pet-manage{display:flex;align-items:center;gap:6px;border:0;background:none;font:inherit;font-size:12px;color:var(--ui-text-secondary);cursor:pointer;padding:6px}.theme-actions button:hover,.pet-manage:hover{color:var(--ui-primary)}.pet-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px}.pet-card{min-width:0;overflow:hidden;border-radius:19px;padding:12px 16px 16px}.pet-card-stage{height:198px;display:flex;justify-content:center;align-items:center;position:relative;background:radial-gradient(ellipse at 50% 65%,color-mix(in srgb,var(--theme-color) 17%,transparent),transparent 68%);margin:0 -8px 9px}.pet-card-stage img{display:block;flex:none}.pet-stage-hint{position:absolute;bottom:2px;font-size:10px;color:var(--ui-text-tertiary);opacity:0}.pet-card:hover .pet-stage-hint{opacity:1}.pet-card-copy h3{font-size:14px;font-weight:600;margin:0 0 7px}.pet-card-copy p{font-size:11px;line-height:1.7;min-height:37px;color:var(--ui-text-secondary);margin:0 0 14px}.pet-tab-count{margin-left:7px;padding:1px 6px;border-radius:6px;background:var(--ui-surface-alt);color:var(--ui-text-tertiary);font-size:11px;font-variant-numeric:tabular-nums}.desktop-pets-empty .n-button{margin-left:12px}.desktop-pets{padding:23px;border-radius:19px}.all-pets-switch{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--ui-text-secondary)}.desktop-pet-list{margin-top:15px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}.desktop-pet-row{display:flex;align-items:center;gap:10px;min-width:0;padding:12px 0;border-top:1px solid var(--ui-border)}.desktop-pet-name{flex:1;min-width:0;display:grid;gap:5px}.desktop-pet-name strong{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.desktop-pet-name small{font-size:10px;color:var(--ui-text-tertiary);line-height:1.5}.pet-mood{font-size:10px;color:var(--ui-text-secondary);padding:4px 7px;border-radius:6px;background:var(--ui-surface-alt)}.pet-empty{padding:50px;text-align:center;border-radius:20px}.pet-empty>svg{color:var(--ui-primary);margin-bottom:14px}.pet-empty h2{font-size:18px;margin:0 0 12px}.pet-empty p,.desktop-pets-empty{font-size:12px;color:var(--ui-text-secondary);line-height:1.8;margin-bottom:18px}.desktop-pets-empty{padding-top:24px;margin:0}.pet-editor{display:grid;gap:22px}.pet-editor-stage{display:flex;justify-content:center;background:radial-gradient(ellipse,#f4e6d840,transparent 70%);padding:12px}.pet-editor>label{display:grid;gap:10px;font-size:12px}.pet-editor>label>span{font-size:11px;color:var(--ui-text-tertiary)}.pet-editor-toggle{display:flex;align-items:center;gap:15px;justify-content:space-between}.pet-editor-toggle b{font-size:12px;font-weight:500}.pet-editor-toggle p{font-size:11px;color:var(--ui-text-tertiary);margin:6px 0 0}@media(max-width:760px){.desktop-pet-list{grid-template-columns:1fr}.pet-section-heading{align-items:flex-start;flex-wrap:wrap}.pet-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.pet-card{padding:8px 12px 12px}.pet-card-stage{height:170px;overflow:hidden}.pet-card-stage img{width:150px;height:150px}}
